cd /src/libxml2 && apply_patch <<'PATCH'
*** Begin Patch
*** Update File: HTMLparser.c
@@
 static int
 htmlCurrentChar(xmlParserCtxtPtr ctxt, int *len) {
     const unsigned char *cur;
     unsigned char c;
     unsigned int val;

+    /*
+     * Make sure that callers never observe an uninitialized character length.
+     * Some callers use the length with NEXTL(len) even on error/EOF paths.
+     */
+    if (len != NULL)
+        *len = 0;
+
     if (ctxt->instate == XML_PARSER_EOF)
 	return(0);
@@

     if ((ctxt->input->end - ctxt->input->cur < 4) &&
         (xmlParserGrow(ctxt) < 0))
         return(0);
*** End Patch
PATCH

cd /src/libxml2 && perl -0777 -i.bak -pe 's/(static int
htmlCurrentChar\(xmlParserCtxtPtr ctxt, int \*len\) \{
    const unsigned char \*cur;
    unsigned char c;
    unsigned int val;

)/$1    /\*
     * Make sure that callers never observe an uninitialized character length.
     * Some callers use the length with NEXTL(len) even on error/EOF paths.
     *
     * Default to 0 to avoid advancing the input cursor if the current
     * character can\x27t be read.
     */
    if (len != NULL)
        *len = 0;

/sg' HTMLparser.c

cd /src/libxml2 && perl -0777 -i -pe 's/ unsigned int c;
\s*int bits, l;
/unsigned int c;
    int bits, l = 1;
/s; s/(\s*c = CUR_CHAR\(l\);
)/$1
    if (c == 0)
        break;
/s' HTMLparser.c

cd /src/libxml2 && perl -i -pe 's/^\s*int bits, l = 1;\s*$/		    int bits, l = 1;/; s/(c = CUR_CHAR\(l\);
)(\s*if\s+\s*\(c <)/$1		    if (c == 0)
		        break;
$2/s' HTMLparser.c

cd /src/libxml2 && perl -0777 -i -pe 's/\}\s*else\s*\{
\s*unsigned int c;
\s*[^
]*int bits, l = 1;
.*?
\s*NEXTL\(l\);
\s*\}/} else {
	    unsigned int c;
	    int bits, l = 1;

	    if (out - buffer > buffer_size - 100) {
		int indx = out - buffer;

		growBuffer(buffer);
		out = &buffer[indx];
	    }	
	    c = CUR_CHAR(l);
	    if (c == 0)
	        break;
	    if      (c <    0x80)
		    { *out++  = c;                bits= -6; }
	    else if (c <   0x800)
		    { *out++  =((c >>  6) & 0x1F) | 0xC0;  bits=  0; }
	    else if (c < 0x10000)
		    { *out++  =((c >> 12) & 0x0F) | 0xE0;  bits=  6; }
	    else
		    { *out++  =((c >> 18) & 0x07) | 0xF0;  bits= 12; }

	    for ( ; bits >= 0; bits-= 6) {
		*out++  = ((c >> bits) & 0x3F) | 0x80;
	    }
	    NEXTL(l);
	}/s' HTMLparser.c && nl -ba HTMLparser.c | sed -n '2838,2885p'

cd /src/libxml2 && perl -0777 -i -pe 's/GROW;
\s*c = CUR_CHAR\(l\);
\s*if \(c == 0\)
\s*break;

\s*if \(c == 0\)
\s*break;/GROW;
    c = CUR_CHAR(l);
    if (c == 0)
        return(NULL);/s' HTMLparser.c && nl -ba HTMLparser.c | sed -n '2684,2705p'

cd /src/libxml2 && git checkout -- HTMLparser.c && perl -0777 -i -pe 's/unsigned int c;
\s*int bits, l;
/unsigned int c;
	    int bits, l = 1;
/s; s/(c = CUR_CHAR\(l\);
)/$1	    if (c == 0) {
	        /\*
	         * htmlCurrentChar may return 0 on encoding/I/O errors
	         * without providing a usable length. Make sure that we always
	         * advance at least one byte to avoid cursor corruption.
	         */
	        c = ' ' ;
	        l = 1;
	    }
/s' HTMLparser.c && grep -n "int bits, l" -n -A4 -B4 HTMLparser.c | head -n 40

cd /src/libxml2 && perl -0777 -i -pe 's/static int
